/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';

const kbPath = 'server/kristy_perimeter_kb.json';
const original = readFileSync(kbPath, 'utf8');
const kb = JSON.parse(original);
assert.equal("'`${JSON.stringify(kb, null, 2)}'"\\n"'`, original, '"'preserve KB formatting');
const card = id => {
  const entry = kb.entries.find(e => e.id === id);
  assert.ok(entry, id);
  return entry;
};
const dyeIds = ['breakfast_cereal', 'frozen_waffles', 'snack_bars', 'snacks', 'yogurt_plain_vs_flavored'];
const antiIds = ['breakfast_cereal', 'crackers', 'potato_chips', 'frozen_nuggets', 'frozen_fries', 'cooking_oils'];
const dyeTip = 'Read the ingredient list for synthetic dyes: Red 40, Yellow 5, Yellow 6 or Blue 1. Take the list with no added color over one naming a dye. “Lake” means a dye that does not dissolve in water; it still counts.';
const antiTip = 'BHA, BHT and TBHQ are preservatives added to fats and fat-containing foods. Read the ingredient list for BHA, BHT or TBHQ. Take a list without them over one naming any.';
const dyeSource = { name: 'CSPI: Artificial colorings (synthetic food dyes)', url: 'https://www.cspi.org/node/7436' };
const tbhqSource = { name: 'CSPI: TBHQ preservative uses', url: 'https://www.cspi.org/node/7416' };
const ewgSource = { name: 'EWG: Food chemicals guide, preservative uses', url: 'https://www.ewg.org/consumer-guides/ewgs-dirty-dozen-guide-food-chemicals-top-12-avoid' };
for (const id of dyeIds) {
  card(id).buying_tips.push(dyeTip);
  card(id).sources.push(dyeSource);
}
for (const id of antiIds) {
  card(id).buying_tips.push(antiTip);
  card(id).sources.push(tbhqSource);
}
card('breakfast_cereal').buying_tips.push('BHT and TBHQ are used in cereals. BHT can appear on the list as “butylated hydroxytoluene.” Certified organic rules prohibit BHT.');
card('breakfast_cereal').sources.push({ name: 'EWG: BHT in food and on ingredient lists', url: 'https://www.ewg.org/foodscores/8806-article-dirty-dozen-food-chemicals-bht/' });
for (const id of ['crackers', 'potato_chips', 'cooking_oils']) card(id).sources.push(ewgSource);
card('cooking_oils').buying_tips.push('TBHQ and propyl gallate are used as preservatives in vegetable oil. Read the list for propyl gallate too; choose one without it.');
card('yogurt_plain_vs_flavored').kristy_take = 'Big tub of plain, add your own berries. Plain has no added sugar.';
const juice = card('pick_juice');
juice.decision = 'Read ingredients: no added color over numbered dyes; most juice is pasteurized, while untreated cold-case juice carries a warning label.';
assert.equal(juice.decision.split(/\\s+/).length, 20);
juice.sources.push(dyeSource);

const pinPath = 'server/test/acceptance/twoLinePin.js';
let pinText = readFileSync(pinPath, 'utf8');
const pinsStart = pinText.indexOf('export const TWO_LINE = ') + 'export const TWO_LINE = '.length;
const pinsEnd = pinText.indexOf(';\\n\\n// Existing consumers', pinsStart);
assert.ok(pinsStart > 0 && pinsEnd > pinsStart);
const pins = JSON.parse(pinText.slice(pinsStart, pinsEnd));
for (const id of new Set([...dyeIds, ...antiIds])) {
  assert.ok(pins[id], id);
  pins[id].buying_tips = card(id).buying_tips;
  pins[id].sources = card(id).sources;
}
pins.yogurt_plain_vs_flavored.kristy_take = card('yogurt_plain_vs_flavored').kristy_take;
pinText = pinText.slice(0, pinsStart) + JSON.stringify(pins, null, 2) + pinText.slice(pinsEnd);
const picksStart = pinText.indexOf('const PICK_PINS = ') + 'const PICK_PINS = '.length;
const picksEnd = pinText.indexOf(';\\n\\nObject.defineProperties', picksStart);
